{
  "name": "fast-file-search",
  "version": "1.0.0",
  "description": "Ung dung tim file nhanh tren may tinh - Fast File Search",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "prestart": "echo Dang khoi dong Fast File Search..."
  },
  "dependencies": {
    "express": "^4.18.2",
    "mime-types": "^2.1.35"
  },
  "engines": {
    "node": ">=12.0.0"
  },
  "keywords": ["file-search", "search-engine", "utility"],
  "license": "MIT"
}

var express = require('express');
var fs = require('fs');
var path = require('path');
var cp = require('child_process');
var os = require('os');
var app = express();
var PORT = 3000;

app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ extended: true }));
app.use(express.static(path.join(__dirname, 'public')));

// ========== INDEX IN MEMORY ==========
var fileIndex = [];
var scanProgress = {
    scanning: false,
    currentFolder: '',
    filesScanned: 0,
    foldersScanned: 0,
    rootPath: ''
};

var defaultIgnoreFolders = [
    'node_modules', 'bin', 'obj', '.git', 'packages',
    '.svn', '.vs', 'Debug', 'Release', '.idea',
    'bower_components', 'vendor', 'dist', 'build'
];

var settings = {
    ignoreFolders: defaultIgnoreFolders.slice(),
    maxPreviewSize: 2 * 1024 * 1024, // 2MB
    enablePreview: true
};

// ========== HELPER: Validate path ==========
function isValidPath(inputPath) {
    if (!inputPath || typeof inputPath !== 'string') {
        return false;
    }
    inputPath = inputPath.trim();
    if (inputPath.length === 0) {
        return false;
    }
    return true;
}

function sanitizePath(inputPath) {
    return path.normalize(inputPath.trim());
}

function formatFileSize(bytes) {
    if (bytes === 0) return '0 B';
    var units = ['B', 'KB', 'MB', 'GB', 'TB'];
    var i = Math.floor(Math.log(bytes) / Math.log(1024));
    return (bytes / Math.pow(1024, i)).toFixed(i > 0 ? 1 : 0) + ' ' + units[i];
}

// ========== API: SCAN DIRECTORY ==========
app.post('/api/scan', function(req, res) {
    var rootPath = req.body.rootPath;
    if (!rootPath) {
        return res.json({ success: false, message: 'Vui long nhap duong dan thu muc.' });
    }
    rootPath = sanitizePath(rootPath);
    if (!fs.existsSync(rootPath)) {
        return res.json({ success: false, message: 'Duong dan khong ton tai.' });
    }
    var stat = fs.statSync(rootPath);
    if (!stat.isDirectory()) {
        return res.json({ success: false, message: 'Duong dan phai la thu muc.' });
    }

    // Reset index
    fileIndex = [];
    scanProgress.scanning = true;
    scanProgress.currentFolder = 'Dang khoi tao...';
    scanProgress.filesScanned = 0;
    scanProgress.foldersScanned = 0;
    scanProgress.rootPath = rootPath;

    res.json({ success: true, message: 'Bat dau quet thu muc.' });

    // Start scanning in background
    scanDirectory(rootPath);
});

function shouldIgnore(folderName) {
    var ignoreList = settings.ignoreFolders;
    for (var i = 0; i < ignoreList.length; i++) {
        if (folderName.toLowerCase() === ignoreList[i].toLowerCase()) {
            return true;
        }
    }
    return false;
}

function scanDirectory(dirPath) {
    try {
        var items = fs.readdirSync(dirPath);
        scanProgress.currentFolder = dirPath;

        for (var i = 0; i < items.length; i++) {
            var itemPath = path.join(dirPath, items[i]);

            try {
                var stat = fs.statSync(itemPath);
                var isDir = stat.isDirectory();
                var itemName = items[i];

                // Skip if folder is in ignore list
                if (isDir && shouldIgnore(itemName)) {
                    scanProgress.foldersScanned++;
                    continue;
                }

                var ext = isDir ? '' : path.extname(itemPath).toLowerCase();
                var fileInfo = {
                    name: itemName,
                    path: itemPath,
                    ext: ext,
                    size: isDir ? 0 : stat.size,
                    sizeFormatted: isDir ? '' : formatFileSize(stat.size),
                    isDirectory: isDir,
                    type: isDir ? 'Thu muc' : 'File',
                    modified: stat.mtime,
                    modifiedFormatted: formatDate(stat.mtime),
                    created: stat.birthtime
                };

                fileIndex.push(fileInfo);

                if (isDir) {
                    scanProgress.foldersScanned++;
                    scanDirectory(itemPath);
                } else {
                    scanProgress.filesScanned++;
                }
            } catch (err) {
                // Skip permission errors silently
                scanProgress.foldersScanned++;
            }
        }
    } catch (err) {
        // Skip permission errors for directories
    }

    scanProgress.currentFolder = '';
    if (scanProgress.currentFolder === '') {
        scanProgress.scanning = false;
    }
}

function formatDate(date) {
    if (!date) return '';
    var d = new Date(date);
    var day = ('0' + d.getDate()).slice(-2);
    var month = ('0' + (d.getMonth() + 1)).slice(-2);
    var year = d.getFullYear();
    var hours = ('0' + d.getHours()).slice(-2);
    var minutes = ('0' + d.getMinutes()).slice(-2);
    return day + '/' + month + '/' + year + ' ' + hours + ':' + minutes;
}

// ========== API: GET SCAN PROGRESS ==========
app.get('/api/scan-progress', function(req, res) {
    res.json({
        scanning: scanProgress.scanning,
        currentFolder: scanProgress.currentFolder,
        filesScanned: scanProgress.filesScanned,
        foldersScanned: scanProgress.foldersScanned,
        rootPath: scanProgress.rootPath,
        totalItems: fileIndex.length
    });
});

// ========== API: SEARCH ==========
app.get('/api/search', function(req, res) {
    var q = (req.query.q || '').trim().toLowerCase();
    var type = (req.query.type || '').trim().toLowerCase();
    var ext = (req.query.ext || '').trim().toLowerCase();
    var root = (req.query.root || '').trim().toLowerCase();
    var dateFilter = (req.query.date || '').trim().toLowerCase();

    if (fileIndex.length === 0) {
        return res.json({
            success: true,
            results: [],
            total: 0,
            message: 'Chua co du lieu index. Vui long index thu muc truoc.'
        });
    }

    var results = [];
    var keywords = [];
    var excludeKeywords = [];

    if (q.length > 0) {
        // Parse keywords, support ! for exclusion
        var parts = q.split(/\s+/);
        for (var i = 0; i < parts.length; i++) {
            var part = parts[i];
            if (part.startsWith('!')) {
                excludeKeywords.push(part.substring(1).toLowerCase());
            } else {
                keywords.push(part.toLowerCase());
            }
        }
    }

    var now = new Date();
    var todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    var yesterdayStart = new Date(todayStart.getTime() - 86400000);
    var weekStart = new Date(todayStart.getTime() - (now.getDay() === 0 ? 6 : now.getDay() - 1) * 86400000);
    var monthStart = new Date(now.getFullYear(), now.getMonth(), 1);

    for (var i = 0; i < fileIndex.length; i++) {
        var item = fileIndex[i];
        var match = true;

        // Filter by search query
        if (keywords.length > 0) {
            var nameMatch = false;
            for (var k = 0; k < keywords.length; k++) {
                var kw = keywords[k];
                // Support wildcard: *.sql, student*.bak
                if (kw.startsWith('*')) {
                    var extOnly = kw.substring(1);
                    if (item.name.toLowerCase().endsWith(extOnly)) {
                        nameMatch = true;
                    } else {
                        nameMatch = false;
                        break;
                    }
                } else if (kw.endsWith('*')) {
                    var prefix = kw.substring(0, kw.length - 1);
                    if (item.name.toLowerCase().startsWith(prefix)) {
                        nameMatch = true;
                    } else {
                        nameMatch = false;
                        break;
                    }
                } else {
                    if (item.name.toLowerCase().indexOf(kw) >= 0) {
                        nameMatch = true;
                    } else {
                        nameMatch = false;
                        break;
                    }
                }
            }
            if (!nameMatch) match = false;
        }

        // Exclusion keywords
        if (match && excludeKeywords.length > 0) {
            for (var e = 0; e < excludeKeywords.length; e++) {
                if (item.name.toLowerCase().indexOf(excludeKeywords[e]) >= 0) {
                    match = false;
                    break;
                }
            }
        }

        // Filter by type (file/folder)
        if (match && type === 'file' && item.isDirectory) match = false;
        if (match && type === 'folder' && !item.isDirectory) match = false;

        // Filter by extension
        if (match && ext.length > 0) {
            var exts = ext.split(',');
            var extMatch = false;
            for (var e = 0; e < exts.length; e++) {
                var extClean = exts[e].trim().toLowerCase();
                if (!extClean.startsWith('.')) extClean = '.' + extClean;
                if (item.ext === extClean) {
                    extMatch = true;
                    break;
                }
            }
            if (!extMatch) match = false;
        }

        // Filter by root path
        if (match && root.length > 0) {
            if (item.path.toLowerCase().indexOf(root) !== 0) {
                match = false;
            }
        }

        // Filter by date
        if (match && dateFilter.length > 0) {
            var modTime = new Date(item.modified).getTime();
            switch (dateFilter) {
                case 'today':
                    if (modTime < todayStart.getTime()) match = false;
                    break;
                case 'yesterday':
                    if (modTime < yesterdayStart.getTime() || modTime >= todayStart.getTime()) match = false;
                    break;
                case 'week':
                    if (modTime < weekStart.getTime()) match = false;
                    break;
                case 'month':
                    if (modTime < monthStart.getTime()) match = false;
                    break;
                // 'all' or empty: no filter
            }
        }

        if (match) {
            results.push(item);
        }
    }

    // Sort: folders first, then by name
    results.sort(function(a, b) {
        if (a.isDirectory && !b.isDirectory) return -1;
        if (!a.isDirectory && b.isDirectory) return 1;
        return a.name.localeCompare(b.name);
    });

    // Limit results to prevent huge response
    var maxResults = 10000;
    var limited = results.slice(0, maxResults);

    res.json({
        success: true,
        results: limited,
        total: results.length,
        shown: limited.length,
        message: ''
    });
});

// ========== API: PREVIEW ==========
app.get('/api/preview', function(req, res) {
    var filePath = req.query.path;
    if (!filePath) {
        return res.json({ success: false, message: 'Thieu tham so duong dan.' });
    }
    filePath = sanitizePath(filePath);

    if (!fs.existsSync(filePath)) {
        return res.json({ success: false, message: 'File khong ton tai.' });
    }

    var stat = fs.statSync(filePath);
    if (stat.isDirectory()) {
        return res.json({ success: false, message: 'Khong the xem truoc thu muc.' });
    }

    var ext = path.extname(filePath).toLowerCase();
    var textExtensions = ['.txt', '.sql', '.cs', '.html', '.htm', '.css', '.js', '.json', '.xml', '.md', '.ini', '.cfg', '.config', '.log', '.bat', '.cmd', '.ps1', '.py', '.java', '.cpp', '.h', '.hpp', '.ts', '.jsx', '.tsx', '.php', '.rb', '.yml', '.yaml', '.env', '.gitignore', '.editorconfig'];
    var imageExtensions = ['.png', '.jpg', '.jpeg', '.webp', '.gif', '.bmp', '.svg', '.ico'];

    // Image files
    if (imageExtensions.indexOf(ext) >= 0) {
        // Return as base64 for security
        try {
            var data = fs.readFileSync(filePath);
            var base64 = data.toString('base64');
            var mimeType = 'image/' + ext.replace('.', '');
            if (ext === '.jpg' || ext === '.jpeg') mimeType = 'image/jpeg';
            if (ext === '.svg') mimeType = 'image/svg+xml';
            return res.json({
                success: true,
                type: 'image',
                data: 'data:' + mimeType + ';base64,' + base64
            });
        } catch (err) {
            return res.json({ success: false, message: 'Loi doc file anh.' });
        }
    }

    // PDF files - serve as URL for iframe
    if (ext === '.pdf') {
        return res.json({
            success: true,
            type: 'pdf',
            data: '/api/serve-file?path=' + encodeURIComponent(filePath)
        });
    }

    // Text files
    if (textExtensions.indexOf(ext) >= 0) {
        if (stat.size > settings.maxPreviewSize) {
            var maxMB = (settings.maxPreviewSize / 1024 / 1024).toFixed(1);
            return res.json({
                success: false,
                message: 'File qua lon (' + formatFileSize(stat.size) + '). Gioi han preview la ' + maxMB + 'MB.'
            });
        }
        try {
            var content = fs.readFileSync(filePath, 'utf-8');
            return res.json({
                success: true,
                type: 'text',
                data: content,
                language: ext.replace('.', '')
            });
        } catch (err) {
            return res.json({ success: false, message: 'Khong the doc file. File co the bi khoa hoac khong phai text.' });
        }
    }

    // Unsupported format
    return res.json({
        success: false,
        type: 'unsupported',
        message: 'Khong ho tro xem truoc dinh dang file nay.',
        info: {
            name: path.basename(filePath),
            size: formatFileSize(stat.size),
            modified: formatDate(stat.mtime),
            ext: ext
        }
    });
});

// ========== API: SERVE FILE FOR PREVIEW ==========
app.get('/api/serve-file', function(req, res) {
    var filePath = req.query.path;
    if (!filePath) {
        return res.status(400).send('Missing path');
    }
    filePath = sanitizePath(filePath);
    if (!fs.existsSync(filePath)) {
        return res.status(404).send('File not found');
    }
    res.sendFile(filePath);
});

// ========== API: OPEN FILE ==========
app.post('/api/open', function(req, res) {
    var filePath = req.body.path;
    if (!filePath) {
        return res.json({ success: false, message: 'Thieu tham so duong dan.' });
    }
    filePath = sanitizePath(filePath);
    if (!fs.existsSync(filePath)) {
        return res.json({ success: false, message: 'File khong ton tai.' });
    }
    try {
        var platform = os.platform();
        if (platform === 'win32') {
            cp.exec('start "" "' + filePath + '"');
        } else if (platform === 'darwin') {
            cp.exec('open "' + filePath + '"');
        } else {
            cp.exec('xdg-open "' + filePath + '"');
        }
        res.json({ success: true, message: 'Da mo file.' });
    } catch (err) {
        res.json({ success: false, message: 'Loi khi mo file.' });
    }
});

// ========== API: OPEN CONTAINING FOLDER ==========
app.post('/api/open-folder', function(req, res) {
    var filePath = req.body.path;
    if (!filePath) {
        return res.json({ success: false, message: 'Thieu tham so duong dan.' });
    }
    filePath = sanitizePath(filePath);
    if (!fs.existsSync(filePath)) {
        return res.json({ success: false, message: 'File khong ton tai.' });
    }
    try {
        var platform = os.platform();
        if (platform === 'win32') {
            cp.exec('explorer /select,"' + filePath + '"');
        } else if (platform === 'darwin') {
            cp.exec('open -R "' + filePath + '"');
        } else {
            cp.exec('xdg-open "' + path.dirname(filePath) + '"');
        }
        res.json({ success: true, message: 'Da mo thu muc chua file.' });
    } catch (err) {
        res.json({ success: false, message: 'Loi khi mo thu muc.' });
    }
});

// ========== API: DELETE FILE ==========
app.post('/api/delete', function(req, res) {
    var filePath = req.body.path;
    if (!filePath) {
        return res.json({ success: false, message: 'Thieu tham so duong dan.' });
    }
    filePath = sanitizePath(filePath);
    if (!fs.existsSync(filePath)) {
        return res.json({ success: false, message: 'File khong ton tai.' });
    }
    try {
        fs.unlinkSync(filePath);
        // Also remove from index
        for (var i = 0; i < fileIndex.length; i++) {
            if (fileIndex[i].path === filePath) {
                fileIndex.splice(i, 1);
                break;
            }
        }
        res.json({ success: true, message: 'Da xoa file.' });
    } catch (err) {
        res.json({ success: false, message: 'Loi khi xoa file. File co the dang duoc su dung.' });
    }
});

// ========== API: SETTINGS ==========
app.get('/api/settings', function(req, res) {
    res.json({
        success: true,
        settings: {
            ignoreFolders: settings.ignoreFolders,
            maxPreviewSize: settings.maxPreviewSize,
            enablePreview: settings.enablePreview
        }
    });
});

app.post('/api/settings', function(req, res) {
    var newSettings = req.body;
    if (newSettings.ignoreFolders) {
        settings.ignoreFolders = newSettings.ignoreFolders;
    }
    if (newSettings.maxPreviewSize) {
        settings.maxPreviewSize = parseInt(newSettings.maxPreviewSize);
    }
    if (typeof newSettings.enablePreview === 'boolean') {
        settings.enablePreview = newSettings.enablePreview;
    }
    res.json({ success: true, message: 'Da luu cai dat.' });
});

// ========== API: GET FILE INFO ==========
app.get('/api/file-info', function(req, res) {
    var filePath = req.query.path;
    if (!filePath) {
        return res.json({ success: false, message: 'Thieu tham so duong dan.' });
    }
    filePath = sanitizePath(filePath);
    if (!fs.existsSync(filePath)) {
        return res.json({ success: false, message: 'File khong ton tai.' });
    }
    try {
        var stat = fs.statSync(filePath);
        var info = {
            name: path.basename(filePath),
            path: filePath,
            size: formatFileSize(stat.size),
            sizeBytes: stat.size,
            isDirectory: stat.isDirectory(),
            created: formatDate(stat.birthtime),
            modified: formatDate(stat.mtime),
            accessed: formatDate(stat.atime),
            ext: path.extname(filePath).toLowerCase()
        };
        res.json({ success: true, info: info });
    } catch (err) {
        res.json({ success: false, message: 'Loi doc thong tin file.' });
    }
});

// ========== START SERVER ==========
app.listen(PORT, function() {
    console.log('==========================================');
    console.log('  Fast File Search Server');
    console.log('  http://localhost:' + PORT);
    console.log('==========================================');
    console.log('  Huong dan:');
    console.log('  1. Mo trinh duyet > http://localhost:' + PORT);
    console.log('  2. Index thu muc can tim');
    console.log('  3. Nhap tu khoa de tim file');
    console.log('==========================================');
});
